CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,alias TEXT NOT NULL UNIQUE,unit TEXT NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users,csrf_hash TEXT NOT NULL,expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users,title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES requests,uploader_id TEXT NOT NULL REFERENCES users,filename TEXT NOT NULL,content TEXT NOT NULL,deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS access_log(id INTEGER PRIMARY KEY,actor_id TEXT,method TEXT NOT NULL,path TEXT NOT NULL,status INTEGER NOT NULL,created_at REAL NOT NULL);
